Constant IVA As Real <- 0.21;
Constant SEMANA As Integer <- 7 * 24;
Algorithm Factura
  Constant SALUDO As String <- "Total: ";
  Define base As Real <- 100.0;
  Write SALUDO, base * (1 + IVA), " (", SEMANA, " horas)";
EndAlgorithm

Constant LIMITE As Integer <- 10;
Algorithm Cambiar
  LIMITE <- 20;
  Write LIMITE;
EndAlgorithm

Constant POT As Integer <- 2 ^ 3;
Algorithm Potencia
  Write POT;
EndAlgorithm
